      ro: "O închisoare colonială din Insulele Andaman și Nicobar, folosită de britanici pentru a exila prizonierii politici.",
      en: "A colonial prison in the Andaman and Nicobar Islands, used by the British to exile political prisoners.",
      es: "Una prisión colonial en las islas Andamán y Nicobar, utilizada por los británicos para el exilio de prisioneros políticos.",
      pt: "Uma prisão colonial nas ilhas Andamã e Nicobar, utilizada pelos britânicos para o exílio de prisioneiros políticos.",
      fr: "Une prison coloniale dans les îles Andaman et Nicobar, utilisée par les Britanniques pour l'exil de prisonniers politiques.",
